import os
import csv
import time
import argparse
import boto3
import pyarrow.dataset as ds
import pyarrow.compute as pc
import pyarrow as pa 
import tempfile
from datetime import datetime


# CONFIG

# Local folder where curated datasets are stored (generated by make_layouts.py)
BASE_DIR = "data/curated"

# Dataset sizes and layouts to benchmark
SIZES = ["S", "M", "L"]
LAYOUTS = ["flat", "by_date", "by_region"]

# Output file for benchmark results
RESULTS_FILE = "results.csv"

# Connection to MinIO bucket (local S3-compatible storage)
# connect_timeout=2 and max_attempts=0 to fail fast if MinIO is not running
BUCKET = "ccbd"
s3 = boto3.client(
    "s3",
    endpoint_url="http://localhost:9000",
    aws_access_key_id="minioadmin",
    aws_secret_access_key="minioadmin",
    config=boto3.session.Config(
        connect_timeout=2,
        retries={"max_attempts": 0}
    )
)

# ARGPARSE

# Run the benchmark with custom parameters without modifying the code
# Example: python bench.py --size S --region Geneva --date-start 2026-01-05 --date-end 2026-01-15
def parse_args():
    parser = argparse.ArgumentParser()

    # Dataset size to benchmark (S, M, L or all for all three)
    parser.add_argument("--size", choices=["S", "M", "L", "all"], default="all")

    # Selective query parameters
    parser.add_argument("--region", default="Zurich")
    parser.add_argument("--date-start", default="2026-01-10")
    parser.add_argument("--date-end", default="2026-01-12")

    # Number of runs to compute the median
    parser.add_argument("--runs", type=int, default=3)

    return parser.parse_args()


# LISTING
# Walks through a local folder and counts Parquet files
# Measures the time it takes (listing time)
# Returns: (listing time, file count, total size in bytes)

def count_files_and_bytes(path):
    start = time.time()
    file_count = 0
    total_bytes = 0

    for root, dirs, files in os.walk(path):
        for file in files:
            if file.endswith(".parquet"):
                file_count += 1
                total_bytes += os.path.getsize(os.path.join(root, file))

    listing_time = time.time() - start
    return listing_time, file_count, total_bytes


# LISTING S3
# Lists objects in an S3 prefix (MinIO)
# Uses a paginator to handle large numbers of objects (>1000)
# Also measures the listing time on the S3 side
# Returns: (listing time, object count, total size in bytes)

def list_s3_objects(prefix):
    start = time.time()
    object_count = 0
    total_bytes = 0
    paginator = s3.get_paginator("list_objects_v2")

    for page in paginator.paginate(Bucket=BUCKET, Prefix=prefix):
        for obj in page.get("Contents", []):
            object_count += 1
            total_bytes += obj["Size"]

    listing_time = time.time() - start
    return listing_time, object_count, total_bytes


# UPLOAD / DOWNLOAD THROUGHPUT

# Measures upload speed from local file to S3 (in MB/s)
def measure_upload_throughput(local_path, s3_key):
    file_size = os.path.getsize(local_path)
    start = time.time()
    s3.upload_file(local_path, BUCKET, s3_key)
    elapsed = time.time() - start
    throughput = (file_size / 1e6) / elapsed  # MB/s
    return throughput

# Measures download speed from S3 to local (in MB/s)
# First download ensures the file exists on S3
# Second download is the one being measured
def measure_download_throughput(s3_key, local_path):
    s3.download_file(BUCKET, s3_key, local_path)
    file_size = os.path.getsize(local_path)
    # re-download to measure (first was just to get size)
    start = time.time()
    s3.download_file(BUCKET, s3_key, local_path)
    elapsed = time.time() - start
    throughput = (file_size / 1e6) / elapsed  # MB/s
    return throughput


# QUERIES

# Selective query: filters on a region and a date range
# Exploits partition pruning for by_region and by_date layouts
# For flat layout, filters on ts directly (no date column)
# Then computes group by event_type with count and mean of value
# Returns: (query time, number of rows, grouped result)

def run_selective_query(path, region, date_start, date_end, layout):
    dataset = ds.dataset(path, format="parquet", partitioning="hive")
    start = time.time()

    if layout == "flat":
        # flat has no date column, filter on ts directly
        ts_start = datetime.strptime(date_start, "%Y-%m-%d")
        ts_end = datetime.strptime(date_end, "%Y-%m-%d")
        filter_expr = (
            (ds.field("region") == region) &
            (ds.field("ts") >= ts_start) &
            (ds.field("ts") <= ts_end)
        )
    
    else:
        filter_expr = (
            (ds.field("region") == region) &
            (ds.field("date") >= date_start) &
            (ds.field("date") <= date_end)
        )

    table = dataset.to_table(
        filter=filter_expr,
        columns=["event_type", "value"]
    )

    grouped = table.group_by("event_type").aggregate([
        ("value", "count"),
        ("value", "mean")
    ])
    query_time = time.time() - start
    return query_time, table.num_rows, grouped

# Broad query: full scan of the dataset without any filter
# Measures the cost of a global aggregation across all layouts
# Returns: (query time, number of rows, grouped result)

def run_broad_query(path):
    dataset = ds.dataset(path, format="parquet", partitioning="hive")
    start = time.time()
    table = dataset.to_table(
        columns=["event_type", "value"]
    )

    grouped = table.group_by("event_type").aggregate([
        ("value", "count"),
        ("value", "mean")
    ])
    query_time = time.time() - start
    return query_time, table.num_rows, grouped


# MEDIAN
# Computes the median of a list of values
# More reliable than the mean to measure query time
# Avoids the influence of outliers (ex: first run slower due to cache)

def median(values):
    sorted_vals = sorted(values)
    n = len(sorted_vals)
    mid = n // 2
    if n % 2 == 0:
        return (sorted_vals[mid - 1] + sorted_vals[mid]) / 2
    return sorted_vals[mid]


# MAIN BENCH
# Runs all measurements for each size and layout combination
# Saves results to results.csv

def main():
    args = parse_args()

    sizes = SIZES if args.size == "all" else [args.size]
    results = []

    print("Starting benchmark...\n")
    print(f"Region: {args.region} | Dates: {args.date_start} → {args.date_end} | Runs: {args.runs}\n")

    for size in sizes:
        for layout in LAYOUTS:
            path = os.path.join(BASE_DIR, size, layout)
            s3_prefix = f"curated/ubereats/{size}/{layout}/"

            print(f"=== {size} - {layout} ===")

            if not os.path.exists(path):
                print("Path missing, skipping\n")
                continue

            # 1. Local listing: file count and total size
            listing_time, file_count, total_bytes = count_files_and_bytes(path)

            # 2. S3 listing: same measure on the MinIO bucket
            try:
                s3_listing_time, s3_object_count, s3_total_bytes = list_s3_objects(s3_prefix)
            except Exception:
                s3_listing_time, s3_object_count, s3_total_bytes = None, None, None

            # 3. Upload/download throughput on a sample file from the layout
            sample_file = None
            for root, dirs, files in os.walk(path):
                for f in files:
                    if f.endswith(".parquet"):
                        sample_file = os.path.join(root, f)
                        break
                if sample_file:
                    break

            upload_throughput = None
            download_throughput = None

            if sample_file:
                s3_key = f"bench_tmp/{size}_{layout}_sample.parquet"
                try:
                    upload_throughput = measure_upload_throughput(sample_file, s3_key)
                    # Use system temp folder (works on both Windows and Mac/Linux)
                    download_throughput = measure_download_throughput(s3_key, os.path.join(tempfile.gettempdir(), "bench_download.parquet"))
                    #download_throughput = measure_download_throughput(s3_key, os.path.join(os.environ["TEMP"], "bench_download.parquet"))
                except Exception:
                    pass
            

            # 4. Selective query: median over runs repetitions
            sel_times = []
            sel_rows = None
            for _ in range(args.runs):
                t, rows, _ = run_selective_query(path, args.region, args.date_start, args.date_end, layout)
                sel_times.append(t)
                sel_rows = rows
            sel_time = median(sel_times)

            # 5. Broad query: median over runs repetitions
            broad_times = []
            broad_rows = None
            for _ in range(args.runs):
                t, rows, _ = run_broad_query(path)
                broad_times.append(t)
                broad_rows = rows
            broad_time = median(broad_times)

            # Print
            print(f"Local listing:      {listing_time:.4f}s | files: {file_count}")
            print(f"S3 listing:         {s3_listing_time if s3_listing_time else 'N/A'}s | objects: {s3_object_count if s3_object_count else 'N/A'}")
            print(f"Upload throughput:  {upload_throughput if upload_throughput else 'N/A'} MB/s")
            print(f"Download throughput:{download_throughput if download_throughput else 'N/A'} MB/s")
            print(f"Selective query:    {sel_time:.4f}s | rows: {sel_rows}")
            print(f"Broad query:        {broad_time:.4f}s | rows: {broad_rows}")
            print()

            # Store results for CSV
            results.append({
                "size": size,
                "layout": layout,
                "local_listing_time_s": round(listing_time, 4),
                "local_file_count": file_count,
                "local_total_size_gb": round(total_bytes / 1e9, 4),
                "s3_listing_time_s": round(s3_listing_time, 4) if s3_listing_time else None,
                "s3_object_count": s3_object_count,
                "s3_total_size_gb": round(s3_total_bytes / 1e9, 4) if s3_total_bytes else None,
                "upload_throughput_mbs": round(upload_throughput, 2) if upload_throughput else None,
                "download_throughput_mbs": round(download_throughput, 2) if download_throughput else None,
                "selective_time_s": round(sel_time, 4),
                "selective_rows": sel_rows,
                "broad_time_s": round(broad_time, 4),
                "broad_rows": broad_rows,
            })

    if not results:
        print("No results to save.")
        return
    
    # Save all results to results.csv
    with open(RESULTS_FILE, "w", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=results[0].keys())
        writer.writeheader()
        writer.writerows(results)

    print(f"Results saved to {RESULTS_FILE}")


if __name__ == "__main__":
    main()